def forward(self, x):
    tokens = x.view(-1, 4 * 2)
    encoded = self.encoder(tokens)
    sequence, hidden = self.recurrent(encoded)
    gated = torch.sigmoid(self.weight(sequence)) * encoded
    return unfamiliar_fusion(gated, hidden)

def forward(self, x):
    width = 4 * 2
    return (x.view(-1, width), width)

